1	import { roundUpInFavourOfMHPCO } from "./rounding.js";
2	
3	export interface Customer {
4	  yearsWithMHPCO: number;
5	}
6	
7	export interface Scenario {
8	  customer: Customer;
9	  steps: Step[];
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: {
15	    type: KnownItemType;
16	    material?: string;
17	    enchantment?: number;
18	    cursed?: boolean;
19	  }[];
20	}
21	
22	export type Step = QuoteStep;
23	
24	export interface ScenarioResults {
25	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
26	}
27	
28	const PROCESSING_FEE = 5;
29	const BASE_PREMIUM_BY_TYPE = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	} as const satisfies Record<string, number>;
37	
38	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
39	const FIRST_INSURANCE_SURCHARGE = 0.1;
40	
41	type Item = QuoteStep["items"][number];
42	
43	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const BLOCK_SIZE = 3;
46	const BLOCK_BASE_PREMIUM = 60;
47	
48	const groupByType = (items: Item[]): Item[][] => [
49	  ...items
50	    .reduce(
51	      (groups, item) =>
52	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
53	      new Map<KnownItemType, Item[]>(),
54	    )
55	    .values(),
56	];
57	
58	const sumOfBasePremiums = (items: Item[]): number =>
59	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
60	
61	// Exactly three alike components form a block at a reduced premium; any
62	// other count is priced per item.
63	//
64	// Deliberate simplification: "component" is not yet enforced, so three alike
65	// swords would also get the block. No test covers it and the spec gives no
66	// example — revisit when one does.
67	const groupBasePremiumOf = (group: Item[]): number =>
68	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
69	
70	const policyBasePremiumOf = (items: Item[]): number =>
71	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
72	
73	const CURSE_SURCHARGE = 0.5;
74	
75	// Item-specific modifiers are charged as a percentage of the affected item's
76	// OWN base premium. See withPolicyWideModifiers for the other scope.
77	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
78	  basePremiumOf(item) * rate;
79	
80	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
81	const HIGH_ENCHANTMENT_THRESHOLD = 5;
82	
83	const isHighlyEnchanted = (item: Item): boolean =>
84	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
85	
86	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
87	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
88	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
89	];
90	
91	// Every modifier rate in this domain combines additively, whether item-scoped
92	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
93	const combinedRate = (rates: number[]): number =>
94	  rates.reduce((total, rate) => total + rate, 0);
95	
96	// Both item modifiers can apply at once, and they stack additively: a cursed
97	// item with enchantment 5 pays 50 % + 30 % of its base premium.
98	const surchargeRateOn = (item: Item): number =>
99	  combinedRate(
100	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
101	      ({ rate }) => rate,
102	    ),
103	  );
104	
105	const surchargeOn = (item: Item): number =>
106	  shareOfOwnBasePremium(item, surchargeRateOn(item));
107	
108	const itemSurchargesOf = (items: Item[]): number =>
109	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
110	
111	// Policy-wide modifiers scale the whole policy base premium, unlike item
112	// modifiers which are charged against the affected item's own base premium.
113	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
114	// its base — not 110 % × 80 %.
115	const LOYALTY_DISCOUNT = -0.2;
116	const LOYALTY_THRESHOLD_YEARS = 2;
117	
118	const isLoyal = (customer: Customer): boolean =>
119	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
120	
121	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
122	
123	// Everything about the policy's context that shifts its rates, as opposed to
124	// the items being priced. Travels as one value because every policy-wide
125	// modifier reads from it.
126	interface PolicyContext {
127	  customer: Customer;
128	  isFollowUpContract: boolean;
129	}
130	
131	const policyWideModifierRatesFor = ({
132	  customer,
133	  isFollowUpContract,
134	}: PolicyContext): number[] => [
135	  FIRST_INSURANCE_SURCHARGE,
136	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
137	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
138	];
139	
140	const withPolicyWideModifiers = (
141	  policyBase: number,
142	  policy: PolicyContext,
143	): number =>
144	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
145	
146	const quotePremium = ({ items }: QuoteStep, policy: PolicyContext): number =>
147	  roundUpInFavourOfMHPCO(
148	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
149	      itemSurchargesOf(items) +
150	      PROCESSING_FEE,
151	  );
152	
153	// A quote is a follow-up contract when the customer already took a quote
154	// earlier in the same scenario.
155	const followsAnEarlierQuote = (steps: Step[], index: number): boolean =>
156	  steps.slice(0, index).some((step) => step.op === "quote");
157	
158	export const runScenario = ({
159	  customer,
160	  steps,
161	}: Scenario): ScenarioResults => ({
162	  results: steps.map((step, index) => ({
163	    premium: quotePremium(step, {
164	      customer,
165	      isFollowUpContract: followsAnEarlierQuote(steps, index),
166	    }),
167	  })),
168	});
